/** A field's value: your own renderer for its name or kind, or the kit's. */
export function FieldValue({ field, record }: { field: FieldMeta; record: Rec }) {
  const value = record[field.name]
  const own = yours[field.name] ?? yours[field.kind]
  if (own?.show) return <>{own.show(value, record)}</>
  if (field.kind === "file" || field.kind === "image") return <FileValue field={field} value={value} />
  if (field.kind === "enum" && value) return <Badge variant="secondary">{format(field, value)}</Badge>
  if (field.kind === "bool") return <Badge variant={value ? "default" : "outline"}>{format(field, value)}</Badge>
  if (field.kind === "relation" && value) {
    const related = record[field.name.replace(/_id$/, "")] as Rec | undefined
    if (related && field.display) return <>{String(related[field.display] ?? related.id)}</>
    return <RelationValue field={field} id={String(value)} />
  }
  if (value === null || value === undefined || value === "") return <span className="text-muted-foreground">—</span>
  if (field.kind === "text" || field.kind === "textarea") return <Highlight text={format(field, value)} />
  return <>{format(field, value)}</>
}

/** A related record, by the field it is shown by: fetched once, then cached. */
function RelationValue({ field, id }: { field: FieldMeta; id: string }) {
  const target = (resources as unknown as Record<string, ResourceMeta>)[field.target ?? ""]
  const related = useQuery({
    queryKey: [target?.name ?? field.target, "get", id],
    queryFn: () => target.api(api as never).get(id),
    enabled: target !== undefined,
    staleTime: 60_000,
  })
  if (related.isPending && target) return <Skeleton className="inline-block h-4 w-24 align-middle" />
  const shown = related.data?.[field.display ?? "id"]
  if (shown === undefined || shown === null) return <span className="text-muted-foreground">{id.slice(0, 8)}</span>
  const text = capitalize(String(shown))
  return (
    <Link
      to={`/${target.name}/${id}` as never}
      className="font-medium underline-offset-4 hover:underline"
      onClick={(e) => e.stopPropagation()}
    >
      {text}
    </Link>
  )
}


/** Back to the resource's list. */
export function BackToList({ resource }: { resource: Resource }) {
  return (
    <Button variant="outline" asChild>
      <Link to={`/${resource.meta.name}` as never}>{t("backTo", { name: resource.meta.label })}</Link>
    </Button>
  )
}

/** A record of the resource; none without an id (a create). */
export function useRecord(resource: Resource, id: string | undefined) {
  return useQuery({
    queryKey: [resource.meta.name, "get", id],
    queryFn: () => resource.meta.api(api as never).get(id ?? ""),
    enabled: id !== undefined,
  })
}

export function ResourceShow({ resource, id }: { resource: Resource; id: string }) {
  const { meta } = resource
  const record = useRecord(resource, id)
  const duplicate = useDuplicate(meta)
  // The keyboard: e edits, Esc or u goes back to the list.
  useKeys({
    e: () => (record.data?.can ?? []).includes("update") && navigate({ to: `/${meta.name}/${id}/edit` as never }),
    Escape: () => navigate({ to: `/${meta.name}` as never }),
    u: () => navigate({ to: `/${meta.name}` as never }),
  })
  const navigate = useNavigate()
  const queryClient = useQueryClient()
  const remove = useMutation({
    mutationFn: (r: Rec) => meta.api(api as never).delete(r.id, { ifMatch: r }),
    onSuccess: () => {
      toast(t("deleted"))
      queryClient.invalidateQueries({ queryKey: [meta.name] })
      navigate({ to: `/${meta.name}` as never })
    },
    onError: (e) => toast(describe(e), "error"),
  })
  if (record.isPending) return <DetailSkeleton fields={(resource.show ?? resource.form).length} />
  if (record.isError) return <ErrorState error={record.error} onRetry={() => record.refetch()} back={<BackToList resource={resource} />} />
  const r = record.data
  const can = r.can ?? []
  const title = resource.title ? String(r[resource.title.name] ?? "") : meta.singular
  const fields = resource.show ?? resource.form
  const relations = resource.relations?.() ?? []
  const value = (f: FieldMeta) => (
    <div key={f.name} className="group/value flex flex-col gap-1">
      <dt className="text-xs font-semibold tracking-wide text-muted-foreground uppercase">{f.label}</dt>
      <dd className="flex min-h-6 items-center gap-1 text-sm font-semibold text-foreground">
        <FieldValue field={f} record={r} />
        {r[f.name] !== null && r[f.name] !== undefined && r[f.name] !== "" && (
          <CopyButton
            text={f.kind === "relation" ? String(r[f.name]) : format(f, r[f.name])}
            label={`${t("copy")} ${f.label}`}
            className="opacity-0 transition-opacity group-hover/value:opacity-100 focus-visible:opacity-100"
          />
        )}
      </dd>
    </div>
  )
  const buttons = (
    <div className="flex flex-col gap-2">
      {can.includes("update") && (
        <Button asChild>
          <Link to={`/${meta.name}/${r.id}/edit` as never}>
            <Pencil /> {t("edit")}
          </Link>
        </Button>
      )}
      {resource.actions
        ?.filter((a) => !a.when || a.when(r))
        .map((a) => (
          <Button
            key={a.label}
            variant={a.destructive ? "destructive-outline" : "outline"}
            onClick={async () => {
              if (a.confirm && !(await ask(a.confirm, { destructive: a.destructive }))) return
              try {
                await a.run(r)
                toast(t("done"))
                queryClient.invalidateQueries({ queryKey: [meta.name] })
              } catch (e) {
                toast(describe(e), "error")
              }
            }}
          >
            {a.icon && <a.icon />} {a.label}
          </Button>
        ))}
      <Button variant="outline" onClick={() => duplicate(r)}>
        <Copy /> {t("duplicate")}
      </Button>
      {can.includes("delete") && (
        <Button
          variant="destructive-outline"
          disabled={remove.isPending}
          onClick={async () => (await ask(t("confirmDelete"), { destructive: true })) && remove.mutate(r)}
        >
          <Trash2 /> {t("delete")}
        </Button>
      )}
    </div>
  )
  return (
    <div className={cn("grid items-start gap-6", relations.length > 0 && "lg:grid-cols-[340px_minmax(0,1fr)]")}>
      <Card className={cn(relations.length === 0 && "max-w-3xl")}>
        <CardContent className="flex flex-col gap-6">
          <div className="flex flex-col items-center gap-3 pt-2 text-center">
            <Picture src={imageOf(resource, r)} name={title} size="lg" />
            <div>
              <h1 className="text-xl font-bold tracking-tight text-foreground">{title}</h1>
              <p className="text-sm text-muted-foreground">{capitalize(meta.singular)}</p>
            </div>
          </div>
          <dl className={cn("grid gap-5", relations.length === 0 && "sm:grid-cols-2")}>{fields.map(value)}</dl>
          {buttons}
        </CardContent>
      </Card>
      {relations.length > 0 && (
        <Card className="py-0">
          <Tabs defaultValue={`${relations[0].resource.meta.name}-${relations[0].param}`} className="gap-0">
            <TabsList className="h-auto w-full justify-start gap-6 rounded-none border-b border-border bg-transparent px-5 pt-3 pb-0">
              {relations.map((rel) => (
                <TabsTrigger
                  key={`${rel.resource.meta.name}-${rel.param}`}
                  value={`${rel.resource.meta.name}-${rel.param}`}
                  className="flex-none rounded-none border-0 border-b-2 border-transparent bg-transparent px-1 pb-3 font-semibold text-muted-foreground shadow-none data-[state=active]:border-primary data-[state=active]:bg-transparent data-[state=active]:text-primary data-[state=active]:shadow-none dark:data-[state=active]:bg-transparent"
                >
                  {rel.label ?? rel.resource.meta.label}
                </TabsTrigger>
              ))}
            </TabsList>
            {relations.map((rel) => (
              <TabsContent key={`${rel.resource.meta.name}-${rel.param}`} value={`${rel.resource.meta.name}-${rel.param}`} className="p-5">
                <ResourceList resource={rel.resource} scope={ { param: rel.param, value: r.id, label: rel.label } } />
              </TabsContent>
            ))}
          </Tabs>
        </Card>
      )}
    </div>
  )
}
